<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientDefaultMaxAgeAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientDefaultMaxAgeAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientDefaultMaxAgeAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getDefaultMaxAge returns null on a freshly created holder.
     */
    public function testDefaultMaxAgeNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDefaultMaxAgeAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isDefaultMaxAgeAssigned());
        $this->assertNull($holder->getDefaultMaxAge());
    }
}
class ImplWithTrustedClientDefaultMaxAgeAttributeHolderUnitTest
{
    use TrustedClientDefaultMaxAgeAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedDefaultMaxAgeRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultDefaultMaxAge();
    }
}
